import{z as l,x as s,o as B,c as d,q as o,j as r,D as A,d as a,s as t,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"增长深化收束","description":"","frontmatter":{"title":"增长深化收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gd-map.md","filePath":"econ/gd-map.md","lastUpdated":1791413859000}'),p={name:"econ/gd-map.md"};function c(h,E,m,f,u,C){const n=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=o('<h1 id="增长深化收束" tabindex="-1">增长深化收束 <a class="header-anchor" href="#增长深化收束" aria-label="Permalink to &quot;增长深化收束&quot;">​</a></h1><div class="epigraph"><p>理论负责列出增长的按钮，证据负责说明哪些按钮连着线；收束就是把六课的按钮与连线钉在同一张图上。</p><footer>—— 据本课程六课整理</footer></div><p><a href="/econ/gd-aid-institutions">上一课</a>把援助与制度的辩论收在「资本缺口买不来激励结构」上。本课收束增长与发展的深钻层：把理论单元的三个模型与实证单元的两类证据合成一张图，按读序重排六课，交代每课留下的按钮。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的不是新模型，而是编排。主干课的 <a href="/econ/endogenous-growth">内生增长</a> 与 <a href="/econ/ak-variety-schumpeter">AK、种类与熊彼特</a> 给了机制分类与直觉；深钻层五课各自补了哪块缺口，互相依赖什么，哪里被数据修正——这些问题不钉下来，五课就只是五篇独立文字。<span class="marginnote">「收束」不是新内容而是导航：把已读的课按依赖顺序钉成一张地图，标注每课留下的坑。读长系列时先找收束篇，能少走回头路——它告诉你哪几课是前置、哪几课可以按需再读。</span>缺口的形状很清楚：理论侧从完整解到部门维度，证据侧从家庭楔子到国家通道，两端在「激励结构」汇合。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按读序重排，每课一句「它做了什么」。第一课 <a href="/econ/gd-endogenous-growth-deep">内生技术的增长模型</a> 把创意的生产写进最优化：专利垄断给创意定价，研发套利条件钉住均衡增长率，肩膀效应与商业窃取决定补贴方向；留下的缺口是规模效应。第二课 <a href="/econ/gd-ideas-rivalry">创意与规模效应</a> 用时间序列证伪 \\(\\phi=1\\)，改写成 \\(g=\\lambda n/(1-\\phi)\\) 的半内生增长：研发补贴降级为水平效应，按钮换成人力资本与市场规模；留下的缺口是单部门。第三课 <a href="/econ/gd-structural-transformation">结构转型</a> 把部门接进来：恩格尔定律与成本病推着份额迁移，结构红利进了发展核算的残差；留下的缺口是微观为什么慢。第四课 <a href="/econ/gd-development-micro">发展的微观证据</a> 用现场试验量楔子：外部性定随机化层级，摩擦定处理形式，外推要过三道门；留下的缺口是国家尺度。第五课 <a href="/econ/gd-aid-institutions">援助与制度</a> 在国家尺度拆渠道：微观项目为正、汇率与问责渠道为负，制度解释以财富反转压过地理。</p>',7)),(B(),r(i,null,{default:A(()=>[t(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E7%AC%AC%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%A5%97%E5%88%A9%E6%9D%A1%E4%BB%B6%E4%B8%8E%E5%9D%87%E8%A1%A1%E5%A2%9E%E9%95%BF%E7%8E%87%22%5D%20--%3E%20L2%5B%22%E7%AC%AC%E4%BA%8C%E8%AF%BE%EF%BC%9A%E8%A7%84%E6%A8%A1%E6%95%88%E5%BA%94%E8%AF%81%E4%BC%AA%EF%BC%8C%E5%8D%8A%E5%86%85%E7%94%9F%E5%A2%9E%E9%95%BF%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E7%AC%AC%E4%B8%89%E8%AF%BE%EF%BC%9A%E9%83%A8%E9%97%A8%E4%BB%BD%E9%A2%9D%E4%B8%8E%E7%BB%93%E6%9E%84%E7%BA%A2%E5%88%A9%22%5D%0A%20%20L3%20--%3E%20L4%5B%22%E7%AC%AC%E5%9B%9B%E8%AF%BE%EF%BC%9A%E5%BE%AE%E8%A7%82%E8%AF%95%E9%AA%8C%E9%87%8F%E6%A5%94%E5%AD%90%22%5D%0A%20%20L4%20--%3E%20L5%5B%22%E7%AC%AC%E4%BA%94%E8%AF%BE%EF%BC%9A%E6%8F%B4%E5%8A%A9%E6%B8%A0%E9%81%93%E4%B8%8E%E5%88%B6%E5%BA%A6%22%5D%0A%20%20L5%20--%3E%20MAP%5B%22%E6%94%B6%E6%9D%9F%EF%BC%9A%E6%BF%80%E5%8A%B1%E7%BB%93%E6%9E%84%E6%98%AF%E4%B8%BB%E9%80%9A%E9%81%93%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("三条贯穿线把六课钉成一张图。其一是增长来源的三次改写：\\(g\\) 外生，到创意是研发的产出，再到创意越来越难找——每改一次，政策按钮就换一批，从「补贴研发」到「人力资本与市场规模」，再到「先测摩擦再定处理」。其二是残差的分解："),e("a",{href:"/econ/convergence-accounting"},"发展核算"),a(" 的 \\(A\\) 到此拆成技术、结构红利、"),e("a",{href:"/econ/misallocation-tfp"},"错配"),a(" 的楔子与制度四块；跨国几十倍的差距主要是水平账——资本深化、错配与结构缺口——不是各国增速的差异，读任何增长模型都要先问它解释的是斜率还是水平。")],-1)),(B(),r(i,null,{default:A(()=>[t(n,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20GAP%5B%22%E8%B7%A8%E5%9B%BD%E6%94%B6%E5%85%A5%E5%B7%AE%E8%B7%9D%3A%20%E6%B0%B4%E5%B9%B3%E8%B4%A6%22%5D%20--%3E%20K%5B%22%E8%B5%84%E6%9C%AC%E6%B7%B1%E5%8C%96%22%5D%0A%20%20GAP%20--%3E%20RES%7B%22%E6%AE%8B%E5%B7%AE%20A%20%E5%9B%9B%E5%88%86%22%7D%0A%20%20RES%20--%3E%20T%5B%22%E6%8A%80%E6%9C%AF%3A%20%E5%88%9B%E6%84%8F%E7%94%9F%E4%BA%A7%E4%B8%8E%E6%89%A9%E6%95%A3%22%5D%0A%20%20RES%20--%3E%20ST%5B%22%E7%BB%93%E6%9E%84%E7%BA%A2%E5%88%A9%3A%20%E4%BB%BD%E9%A2%9D%E8%BF%81%E7%A7%BB%22%5D%0A%20%20RES%20--%3E%20M%5B%22%E9%94%99%E9%85%8D%E6%A5%94%E5%AD%90%3A%20%E8%B5%84%E6%BA%90%E5%88%B0%E9%94%99%E6%89%8B%22%5D%0A%20%20RES%20--%3E%20INS%5B%22%E5%88%B6%E5%BA%A6%3A%20%E6%BF%80%E5%8A%B1%E7%BB%93%E6%9E%84%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<p><span class="marginnote">水平账与增速账的直觉：两辆车速度不同只解释里程差越拉越大（增速账），不解释起点为何差 100 公里（水平账）。跨国几十倍的收入差距主要是几十年攒下的里程存量，不是今天速度差的直接倍数——所以增长模型解释斜率，水平差距要另找资本深化、错配与结构的账。</span>其三是证据的分层：试验管内部效度，外推管三道门，宏观证据管规格扫描；三段各管一段，组合的口径与 <a href="/econ/pe-case-map">政策评估案例与收束</a> 同源。</p><p><span class="marginnote">六课共用的错法只有一个原型：把局部结论当全局参数。第一代的规模效应、肥料的边际回报、援助的条件有效，都是同一类外推错误在不同尺度上的重演。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有统一模型把六课装进去：创意模型与结构模型互补而非嵌套，微观参数不进结构模型就只是参数，宏观识别到「渠道为负」为止、给不出权重的精确值。<span class="marginnote">初学者容易期待一门课给出增长的「最终答案」。收束给出的恰恰相反：每个模型只管一段——创意模型管斜率，试验管楔子，援助研究管渠道。把局部答案当全图，正是本层反复演示的错误原型：规模效应、肥料回报、条件有效都是同一类外推错误。</span>制度如何被改变——深钻层只论证了援助买不来它，没有给出改变它的可信路径，这是留下的问题而不是结论。本课程到此收束，深钻层之后进入附录：论文与前沿不再有后续课接续。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>理论单元的依赖链：套利条件 → 规模效应证伪 → 部门维度；每步修正都换掉一批政策按钮。</li><li>残差四分：技术、结构红利、错配、制度；跨国差距主要是水平账，不是增速账。</li><li>证据分层：试验、外推、宏观规格扫描各管一段，单一证据不单独定结论。</li><li>激励结构是两条证据链的汇合点：微观楔子与宏观渠道都指向它。</li><li>制度的可改变性是留下的问题，不是本课程的结论。</li><li>出处：本课程六课所引文献；编排口径与各主干课的链接见正文。</li></ul>',6))])}const F=l(p,[["render",c]]);export{g as __pageData,F as default};
